// Ouvrir la fiche du Sauce Labs Backpack depuis son lien de titre stable.
cy.get('[data-test="item-4-title-link"]').click();
// Vérifier que la navigation a ouvert la page de détail du produit.
cy.url().should('include', '/inventory-item.html?id=4');
// Vérifier que le nom du produit sélectionné est visible sur la fiche.
cy.get('[data-test="inventory-item-name"]').should('be.visible').and('have.text', 'Sauce Labs Backpack');
// Vérifier que le prix du produit sélectionné est visible sur la fiche.
cy.get('[data-test="inventory-item-price"]').should('be.visible').and('have.text', '$29.99');
// Vérifier que le bouton 'Add to cart' est visible sur la fiche.
cy.get('[data-test="add-to-cart"]').should('be.visible').and('have.text', 'Add to cart');
// Vérifier que la description du produit sélectionné est visible sur la fiche.
cy.get('[data-test="inventory-item-desc"]').should('be.visible').and('have.text', 'carry.allTheThings() with the sleek, streamlined Sly Pack that melds uncompromising style with unequaled laptop and tablet protection.');
